def validate_ModelingCommand(value: ModelingCommand) -> None:
    if isinstance(value, ModelingCommandCreateAsset):
        validate_ImageAsset(value.asset)
    elif isinstance(value, ModelingCommandReplaceAsset):
        validate_ImageAsset(value.asset)
    elif isinstance(value, ModelingCommandCreateMesh):
        validate_Mesh(value.mesh)
    elif isinstance(value, ModelingCommandReplaceMesh):
        validate_Mesh(value.mesh)
    elif isinstance(value, ModelingCommandCreateParameter):
        validate_Parameter(value.parameter)
    elif isinstance(value, ModelingCommandReplaceParameter):
        validate_Parameter(value.parameter)
    elif isinstance(value, ModelingCommandCreatePart):
        validate_Part(value.part)
    elif isinstance(value, ModelingCommandReplacePart):
        validate_Part(value.part)
    elif isinstance(value, ModelingCommandCreateTransform):
        validate_Transform(value.transform)
    elif isinstance(value, ModelingCommandReplaceTransform):
        validate_Transform(value.transform)
    elif isinstance(value, ModelingCommandCreateBinding):
        validate_MeshBinding(value.binding)
    elif isinstance(value, ModelingCommandReplaceBinding):
        validate_MeshBinding(value.binding)
    elif isinstance(value, ModelingCommandCreateSceneBinding):
        validate_SceneBinding(value.binding)
    elif isinstance(value, ModelingCommandReplaceSceneBinding):
        validate_SceneBinding(value.binding)
    elif isinstance(value, ModelingCommandCreateBlendKeyTable):
        validate_BlendShapeKeyTable(value.table)
    elif isinstance(value, ModelingCommandReplaceBlendKeyTable):
        validate_BlendShapeKeyTable(value.table)
    elif isinstance(value, ModelingCommandCreateBlendConstraint):
        validate_BlendShapeConstraint(value.constraint)
    elif isinstance(value, ModelingCommandReplaceBlendConstraint):
        validate_BlendShapeConstraint(value.constraint)
    elif isinstance(value, ModelingCommandCreateBlendBinding):
        validate_BlendShapeBinding(value.binding)
    elif isinstance(value, ModelingCommandReplaceBlendBinding):
        validate_BlendShapeBinding(value.binding)
    elif isinstance(value, ModelingCommandCreateGlue):
        validate_Glue(value.glue)
    elif isinstance(value, ModelingCommandReplaceGlue):
        validate_Glue(value.glue)
    elif isinstance(value, ModelingCommandCreateOffscreen):
        validate_Offscreen(value.offscreen)
    elif isinstance(value, ModelingCommandReplaceOffscreen):
        validate_Offscreen(value.offscreen)
    elif isinstance(value, ModelingCommandScene):
        validate_SceneEdit(value.intent)
    elif isinstance(value, ModelingCommandOrganization):
        validate_OrganizationEdit(value.intent)
    elif isinstance(value, ModelingCommandBinding):
        validate_BindingAuthoringEdit(value.intent)
    elif isinstance(value, ModelingCommandContent):
        validate_SceneContentEdit(value.intent)
    elif isinstance(value, ModelingCommandReferences):
        validate_ReferenceEdit(value.intent)
    elif isinstance(value, ModelingCommandResource):
        validate_ResourceEdit(value.intent)
    elif isinstance(value, ModelingCommandDocument):
        validate_DocumentAuthoringEdit(value.intent)
    elif isinstance(value, ModelingCommandAttachment):
        validate_AttachmentEdit(value.intent)
    elif isinstance(value, ModelingCommandReplaceModelSetup):
        validate_ModelSetup(value.setup)
    elif isinstance(value, ModelingCommandReplaceHierarchyOrder):
        validate_HierarchyOrder(value.order)
    elif isinstance(value, ModelingCommandReplaceEditorState):
        validate_EditorState(value.state)
    elif isinstance(value, ModelingCommandReplaceDrawOrderGroups):
        if not isinstance(value.groups, tuple):
            raise TypeError("Expected an immutable tuple")
        for v0 in value.groups:
            validate_DrawOrderGroup(v0)
    elif isinstance(value, ModelingCommandEraseObject):
        if not isinstance(value.id, str):
            raise ValueError("Expected string")
    elif isinstance(value, ModelingCommandRenameMesh):
        if not isinstance(value.id, str):
            raise ValueError("Expected string")
        if not isinstance(value.name, str):
            raise ValueError("Expected string")
    elif isinstance(value, ModelingCommandUpdatePositions):
        if not isinstance(value.id, str):
            raise ValueError("Expected string")
        if not isinstance(value.vertex_ids, tuple):
            raise TypeError("Expected an immutable tuple")
        for v0 in value.vertex_ids:
            if type(v0) is not int or not 0 <= v0 < 4294967296:
                raise ValueError("Expected u32")
        if not isinstance(value.positions, tuple):
            raise TypeError("Expected an immutable tuple")
        for v0 in value.positions:
            validate_Vec2(v0)
    elif isinstance(value, ModelingCommandSetMeshKeyform):
        if not isinstance(value.id, str):
            raise ValueError("Expected string")
        validate_MeshKeyform(value.keyform)
    elif isinstance(value, ModelingCommandSetSceneKeyform):
        if not isinstance(value.id, str):
            raise ValueError("Expected string")
        validate_SceneKeyform(value.keyform)
    elif isinstance(value, ModelingCommandRemeshRectangleGrid):
        if not isinstance(value.id, str):
            raise ValueError("Expected string")
        if type(value.columns) is not int or not 0 <= value.columns < 18446744073709551616:
            raise ValueError("Expected usize")
        if type(value.rows) is not int or not 0 <= value.rows < 18446744073709551616:
            raise ValueError("Expected usize")
    elif isinstance(value, ModelingCommandReplaceTopology):
        validate_GeometrySnapshot(value.source)
        validate_TopologyReplacement(value.replacement)
    elif isinstance(value, ModelingCommandManualMesh):
        if not isinstance(value.mesh_id, str):
            raise ValueError("Expected string")
        validate_SourceRef(value.expected)
        validate_ManualMeshOperation(value.operation)
    else:
        raise TypeError("Expected ModelingCommand")

