def validate_ResourceEdit(value: ResourceEdit) -> None:
    if isinstance(value, ResourceEditCreate):
        if not isinstance(value.id, str):
            raise ValueError("Expected string")
        if not isinstance(value.name, str):
            raise ValueError("Expected string")
        if value.before is not None:
            if not isinstance(value.before, str):
                raise ValueError("Expected string")
    elif isinstance(value, ResourceEditPatchName):
        if not isinstance(value.id, str):
            raise ValueError("Expected string")
        if not isinstance(value.expected, str):
            raise ValueError("Expected string")
        if not isinstance(value.name, str):
            raise ValueError("Expected string")
    elif isinstance(value, ResourceEditSetContent):
        if not isinstance(value.id, str):
            raise ValueError("Expected string")
        if value.expected is not None:
            validate_ImageContent(value.expected)
        if value.content is not None:
            validate_ImageContent(value.content)
    elif isinstance(value, ResourceEditReorder):
        if not isinstance(value.ids, tuple):
            raise TypeError("Expected an immutable tuple")
        for v0 in value.ids:
            if not isinstance(v0, str):
                raise ValueError("Expected string")
        if value.before is not None:
            if not isinstance(value.before, str):
                raise ValueError("Expected string")
    elif isinstance(value, ResourceEditDuplicate):
        if not isinstance(value.source, str):
            raise ValueError("Expected string")
        if not isinstance(value.id, str):
            raise ValueError("Expected string")
        if not isinstance(value.name, str):
            raise ValueError("Expected string")
        if value.before is not None:
            if not isinstance(value.before, str):
                raise ValueError("Expected string")
    elif isinstance(value, ResourceEditDelete):
        if not isinstance(value.id, str):
            raise ValueError("Expected string")
        if value.replacement is not None:
            validate_SceneReference(value.replacement)
    else:
        raise TypeError("Expected ResourceEdit")

def encode_ResourceEdit(value: ResourceEdit) -> object:
    if isinstance(value, ResourceEditCreate):
        return {'operation': 'create', **cast(Mapping[str, object], {'id': value.id, 'name': value.name, 'before': None if value.before is None else value.before})}
    elif isinstance(value, ResourceEditPatchName):
        return {'operation': 'patch_name', **cast(Mapping[str, object], {'id': value.id, 'expected': value.expected, 'name': value.name})}
    elif isinstance(value, ResourceEditSetContent):
        return {'operation': 'set_content', **cast(Mapping[str, object], {'id': value.id, 'expected': None if value.expected is None else encode_ImageContent(value.expected), 'content': None if value.content is None else encode_ImageContent(value.content)})}
    elif isinstance(value, ResourceEditReorder):
        return {'operation': 'reorder', **cast(Mapping[str, object], {'ids': [v0 for v0 in value.ids], 'before': None if value.before is None else value.before})}
    elif isinstance(value, ResourceEditDuplicate):
        return {'operation': 'duplicate', **cast(Mapping[str, object], {'source': value.source, 'id': value.id, 'name': value.name, 'before': None if value.before is None else value.before})}
    elif isinstance(value, ResourceEditDelete):
        return {'operation': 'delete', **cast(Mapping[str, object], {'id': value.id, 'replacement': None if value.replacement is None else encode_SceneReference(value.replacement)})}
    raise TypeError("Expected ResourceEdit")

def read_ResourceEdit(value: object) -> ResourceEdit:
    if isinstance(value, (ResourceEditCreate, ResourceEditPatchName, ResourceEditSetContent, ResourceEditReorder, ResourceEditDuplicate, ResourceEditDelete,)): return value
    r = record(value)
    tag = string(r['operation'])
    if tag == 'create':
        f = record(r)
        return ResourceEditCreate(id=string(f['id']), name=string(f['name']), before=None if f.get('before', None) is None else string(f.get('before', None)))
    elif tag == 'patch_name':
        f = record(r)
        return ResourceEditPatchName(id=string(f['id']), expected=string(f['expected']), name=string(f['name']))
    elif tag == 'set_content':
        f = record(r)
        return ResourceEditSetContent(id=string(f['id']), expected=None if f.get('expected', None) is None else read_ImageContent(f.get('expected', None)), content=None if f.get('content', None) is None else read_ImageContent(f.get('content', None)))
